for k in range(K):
    for i in C:
        for j in C:
            if i != j:
                m.addCons(
                    t[(j, k)] >= t[(i, k)] + s + d[(i, j)] - M * (1 - x[(i, j, k)]),
                    f"tp_{i}_{j}_{k}"
                )

