for k in range(K):
    for i in C:
        for j in C:
            if i != j:
                m.addCons(
                    t[(j, k)] >= tw[i][0] + s + d[(i, j)] - M * (1 - x[(i, j, k)]),
                    f"wait_{i}_{j}_{k}"
                )

